#!/usr/bin/env bash
# Removes a project previously generated by create-example.sh. Refuses to
# touch anything that doesn't look like one of our generated examples, as a
# safety net against a wrong or typo'd target directory.
set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
BASE_DIR="$(cd "$SCRIPT_DIR/.." && pwd)"

EXAMPLE_NAME="${1:-pizza-maker-simulator}"
TARGET_DIR="${2:-$BASE_DIR/../$EXAMPLE_NAME}"

if [ ! -e "$TARGET_DIR" ]; then
  echo "Nothing to remove: $TARGET_DIR does not exist."
  exit 0
fi

MARKER='Generated by `make example`'
if ! grep -qF "$MARKER" "$TARGET_DIR/README.md" 2>/dev/null; then
  echo "Refusing to remove $TARGET_DIR: it doesn't look like a generated example" >&2
  echo "(no '$MARKER' line in its README.md). Remove it by hand if you're sure." >&2
  exit 1
fi

# Stop any containers/volumes it started before deleting the directory their
# compose file lives in. Best-effort: don't fail the whole removal just
# because docker/podman isn't available or the stack was already down.
if [ -f "$TARGET_DIR/Makefile" ]; then
  ( cd "$TARGET_DIR" && make clean ) 2>&1 | sed 's/^/  /' || true
fi

echo "Removing $TARGET_DIR"
rm -rf "$TARGET_DIR"
echo "Done."
